from tests_src import T, Q2, TF

T(26, "26-1", "The Canoe on Crane Lake", "Narrative", [
"Ravi and his cousin Elsie had waited the whole year for the canoe trip. Their uncle Tomas, who managed the outdoor centre on Crane Lake, had promised that this summer they could paddle out to Heron Island by themselves. “Hug the shore until you reach the reeds,” he said, handing them each an orange life jacket, “and after that it is a straight line across. You will be there in twenty minutes.” Then he pressed a small compass into Elsie’s palm. “Just in case,” he added, with a wink.",
"The lake lay flat and silver in the early light, and the canoe glided over it almost without a sound. Ravi sat at the front and Elsie at the back, and their paddles dipped in perfect time while a pale mist hung low over the water. Heron Island was a dark smudge on the horizon, and it seemed to grow larger with every stroke.",
"Halfway across, however, the mist thickened until it rolled over the surface in heavy white folds, swallowing the shore behind them and then the island ahead. Ravi turned his head this way and that, but there was nothing to see except grey. “Which way now?” he asked. Elsie stopped paddling. “I thought you were watching the island,” she said. “I was,” Ravi replied, “right up until it vanished.”",
"Then Elsie remembered the compass in her pocket. “Uncle Tomas said the island lies north-east of the jetty,” she said slowly. “If we follow the needle, we ought to reach it.” She balanced the compass on her knee and waited while the needle trembled and finally settled. Ravi noticed that her hands were not quite steady, although her voice sounded perfectly calm. “Steer us that way,” she said, “and I will tell you whenever we begin to drift.”",
"It was slow, careful work. Ravi counted his strokes aloud in a voice that was a little thinner than usual, and after every fifty strokes Elsie checked the needle. Somewhere in the whiteness a heron called, and both cousins jumped so violently that the canoe wobbled. The minutes stretched out, and Ravi began to wonder whether they had chosen the wrong direction after all.",
"Just as his arms began to ache, a row of dark pine trees loomed out of the mist, and the front of the canoe scraped onto a beach of small grey pebbles. Ravi let out an enormous breath, and Elsie began to laugh, softly at first and then so helplessly that the canoe rocked beneath them. Far behind them, a horn sounded across the water. Uncle Tomas had seen the mist rolling in from the jetty, and he was already on his way to find them.",
"“Next time,” said Ravi, wiping his forehead, “I will watch the compass as well as the island.” Elsie shook her head, smiling. “Next time,” she said, “we both will.”",
], [
 dict(d="2b",k="mc",m=1,q="How long did Uncle Tomas say the trip to the island would take?",opts=["Ten minutes","Twenty minutes","Thirty minutes","Forty minutes"],a="B"),
 dict(d="2b",k="find",m=1,q="Find and copy one word from paragraph 2 that describes the colour of the lake.",a="silver",g="Accept “silver” only."),
 dict(d="2a",k="mc",m=1,q="In paragraph 3, what does the word “vanished” mean?",opts=["Grew bigger","Disappeared from sight","Moved closer","Became darker"],a="B"),
 dict(d="2b",k="short",m=2,q="Give two things that Uncle Tomas handed to the cousins before they set off.",a="Life jackets (one each); a compass (given to Elsie).",g="1 mark for each of: life jackets; compass. Max 2."),
 dict(d="2d",k="short",m=1,q="Why did Elsie stop paddling in paragraph 3?",a="She realised they could not see the island, so she did not know which way to go.",g="Accept: they were lost / the mist hid the island / she was unsure of the direction."),
 dict(d="2g",k="short",m=1,q="The writer says the mist was “swallowing the shore”. What does this word choice suggest about the mist?",a="That it covered the shore completely and quickly, so it disappeared.",g="Accept any answer about the mist hiding, covering or taking over the shore completely."),
 dict(d="2c",k="order",m=1,q="Number the events from 1 to 4 to show the order they happened in the story.",items=["Elsie checked the compass.","The mist thickened.","The canoe reached the pebble beach.","Uncle Tomas gave the cousins life jackets."],a=[3,2,4,1],g=Q2),
 dict(d="2d",k="short",m=1,q="Elsie’s “hands were not quite steady, although her voice sounded perfectly calm”. What does this tell you about how she felt?",a="She was a little scared or nervous inside but was trying to stay calm for Ravi.",g="Accept: nervous but pretending to be calm / brave. Do not accept “happy” or “bored”."),
 dict(d="2d",k="short",m=1,q="What clue in paragraph 5 shows that Ravi was worried?",a="His voice was thinner than usual / he began to wonder whether they had chosen the wrong direction / he jumped at the heron.",g="Accept any one of these clues."),
 dict(d="2b",k="tf",m=1,q="Tick True or False for each sentence.",items=["The cousins had waited a whole year for the trip.","Elsie sat at the front of the canoe.","The cousins reached the island safely.","Uncle Tomas set out to find them."],a=["T","F","T","T"],g=TF),
 dict(d="2c",k="mc",m=1,q="Which sentence best sums up paragraph 4?",opts=["Elsie is angry with Ravi for getting them lost.","Elsie uses the compass to help them find the way.","Ravi has forgotten the way to the jetty.","The cousins decide to go back to the shore."],a="B"),
 dict(d="2d",k="mc",m=1,q="Which two words best describe Elsie in this story?",opts=["Careless and bored","Shy and forgetful","Calm and sensible","Loud and bossy"],a="C"),
 dict(d="2e",k="short",m=1,q="What do you think Uncle Tomas will say when he reaches the cousins? Give a reason for your answer.",a="He will be pleased/relieved that they are safe, and may praise Elsie for using the compass.",g="Accept a sensible prediction (relieved, pleased, proud, checking they are safe) with a reason from the story, such as that he had come to find them or had given the compass “just in case”."),
])

T(26, "26-2", "The Mill at the Bottom of the Sea", "Narrative", [
"Long ago, in a cold northern land of steep fjords and dark pine forests, there lived a fisherman named Anders, who was so poor that in some winters his family had nothing to eat but turnips and a little stale bread. One morning, while he was mending his nets on the shore, a stranger with a long grey beard stopped beside him and studied him thoughtfully. “You look like a man who shares whatever he has,” said the stranger. “I have a gift for you.”",
"From beneath his cloak he drew a small stone mill, no bigger than a loaf of bread, and placed it in the fisherman’s hands. “Turn the handle and speak your wish,” he explained. “The mill will keep grinding for as long as you please, but when you have enough, you must say, ‘Stop, mill, stop,’ and it will rest.” Before Anders could thank him, the stranger had vanished, leaving only a line of footprints in the sand.",
"Anders tried the mill at once. “Grind me a loaf of bread,” he whispered, and as he turned the handle, out tumbled a warm, golden loaf. Within days his table was piled high with cheese, apples and herrings. Yet Anders never kept the bounty to himself; each week he shared it generously with his neighbours, and the village had never been so cheerful.",
"News of the mill spread across the fjords and eventually reached the ears of a ship’s captain named Borg, a shrewd man who was also extremely greedy. He longed to possess the mill, and on a moonless night he crept into Anders’s cottage and carried it away to his ship. As soon as they were safely out at sea, he turned to his crew with a satisfied grin. “Now we shall never go hungry,” he declared. “What shall we ask for? Salt! We can sell it for a fortune.”",
"“Grind me salt,” he ordered, turning the handle. White crystals began to pour out, and the crew cheered. But Borg had never troubled to ask how the mill was stopped, and now he could not recall a single word of what he had overheard. The salt gushed faster and faster, rising around the sailors’ boots and then up to their knees. “Stop!” shouted Borg. “Halt! Enough!” But the mill paid no attention.",
"The ship sank lower and lower beneath its glittering burden. Just in time, Borg and his crew scrambled into a small rowing boat and paddled away, coughing and blinking. Behind them the great ship slid beneath the waves, and the little mill went down with it, still grinding.",
"Some people say that the mill lies on the sea floor to this very day. It has never found the words to make it stop, and so it goes on making salt, which is why, they say, the sea tastes salty.",
], [
 dict(d="2b",k="short",m=1,q="What did the fisherman, Anders, do to help his neighbours?",a="He shared the food the mill made with them.",g="Accept: he shared his food / gave them food from the mill."),
 dict(d="2b",k="find",m=1,q="Find and copy the words that tell you how big the mill was.",a="no bigger than a loaf of bread",g="Accept “no bigger than a loaf of bread” or “small stone mill”."),
 dict(d="2a",k="mc",m=1,q="In paragraph 4, what does the word “greedy” mean?",opts=["Wanting far more than you need","Feeling very tired","Being cruel to animals","Working very hard"],a="A"),
 dict(d="2d",k="short",m=1,q="The stranger said, “You look like a man who shares whatever he has.” Why did the stranger give the mill to Anders?",a="Because Anders was kind and generous, so he deserved a gift / the mill would be used well.",g="Accept any answer that links the gift to Anders being kind, generous or sharing."),
 dict(d="2c",k="order",m=1,q="Number the events from 1 to 4 to show the order they happened in the story.",items=["Borg asked the mill for salt.","The stranger gave Anders the mill.","Borg stole the mill.","The crew escaped in a rowing boat."],a=[3,1,2,4],g=Q2),
 dict(d="2d",k="short",m=1,q="Why could Borg not stop the mill?",a="He had not listened to / did not know the words that stop it.",g="Accept: he did not know the right words / he had not asked how to stop it / he forgot them."),
 dict(d="2g",k="short",m=1,q="The salt gushed “faster and faster”. How does the writer’s repetition make you feel as you read this part?",a="It makes the reader feel that the salt is out of control and the crew is in trouble.",g="Accept any answer about growing speed, panic, tension or the situation getting worse."),
 dict(d="2b",k="tf",m=1,q="Tick True or False for each sentence.",items=["Anders lived by the sea.","The mill could only grind out bread.","Borg took the mill from Anders’s cottage at night.","The crew were lost when the ship sank."],a=["T","F","T","F"],g=TF),
 dict(d="2d",k="short",m=2,q="Give two clues from the text that show Borg was not an honest man.",a="He crept into the cottage at night; he carried the mill off / stole it; he wanted the mill only for himself; he planned to sell salt for a fortune.",g="1 mark for each clue. Max 2."),
 dict(d="2c",k="mc",m=1,q="What is the main message of this story?",opts=["Sailors should always carry a mill.","Being greedy can lead to trouble.","Fishermen never go hungry.","Strangers should not be trusted."],a="B"),
 dict(d="2d",k="short",m=1,q="Look at the last paragraph. What is this part of the story trying to explain?",a="Why the sea is salty.",g="Accept: why the sea tastes salty / how the sea got its salt."),
 dict(d="2a",k="find",m=1,q="Find and copy one word from paragraph 6 that means “sparkling”.",a="glittering",g="Accept “glittering” only."),
 dict(d="2e",k="short",m=1,q="Do you think Anders would have known how to stop the mill? Explain your answer.",a="Yes, because the stranger told him the words “Stop, mill, stop”.",g="Accept yes with a reason based on paragraph 2."),
])

T(26, "26-3", "Dumplings for the New Year", "Narrative", [
"Every year, on the last evening before the New Year, the whole of Mei-Ling’s family squeezed into her grandmother’s tiny flat to make dumplings together. Aunts, uncles and cousins arrived clutching mixing bowls and rolling pins, and Po Po, Mei-Ling’s grandmother, presided over the kitchen like a general commanding an army. This year, for the first time, Mei-Ling was considered old enough to help.",
"“Watch my hands,” said Po Po, laying a circle of dough on Mei-Ling’s palm. She dropped a spoonful of pork and chives into the centre, folded the dough over, and pinched the edge into a row of neat little pleats, as swiftly as a bird tucks in its wing. “Now you try.”",
"Mei-Ling’s first dumpling looked like a squashed slipper. The filling oozed out of one side, and the pleats collapsed the moment she pressed them. Her cousin Jun snorted with laughter. “That one is going straight to the compost!” he teased. Mei-Ling’s cheeks burned as she glanced at the tray in front of her, where dozens of flawless dumplings stood in rows like tiny white boats.",
"“Take no notice of him,” Po Po said gently. “When I was your age, mine burst open in the water. Your fingers will learn; it only takes a little patience.” She demonstrated again, slowly, and Mei-Ling copied every movement with fierce concentration. By the tenth dumpling the pleats had begun to hold, and by the twentieth she was humming along to the music on the radio.",
"Then Po Po held up a shiny silver coin between finger and thumb. “Every year, we hide one of these inside a single dumpling,” she explained. “Whoever finds it will have good luck for the whole year.” While the children watched, she wrapped the coin in dough and shuffled it into the tray, so that nobody could possibly tell which dumpling contained it.",
"When the dumplings emerged from the steaming pot, everybody crowded around the table, and the kitchen filled with the smell of ginger and warm dough. Mei-Ling chose one at random and bit into it. Something hard clicked against her teeth. She drew out the coin, gleaming and wet, and held it up in astonishment.",
"“Mei-Ling has the luck!” cried her aunt, and the whole room applauded. Jun stared at her, and then, to her surprise, he grinned. “Was that one of the squashed ones?” he asked. Mei-Ling looked down at the little dumpling on her plate, which was lopsided, with the pleats undone at one end. “It was,” she said. Po Po smiled a secret smile and passed her the soy sauce.",
], [
 dict(d="2b",k="mc",m=1,q="When did the family make dumplings each year?",opts=["On Po Po’s birthday","On the last evening before the New Year","On the first day of summer","At the end of each week"],a="B"),
 dict(d="2b",k="short",m=1,q="What did Po Po put inside the dumplings as a filling?",a="Pork and chives.",g="Accept pork and chives (both needed) or “pork” if the chives are missing."),
 dict(d="2a",k="mc",m=1,q="In paragraph 1, what does the phrase “presided over the kitchen like a general” suggest about Po Po?",opts=["She was frightened of the kitchen","She was in charge and everyone listened to her","She was tired and wanted to rest","She did not know how to cook"],a="B"),
 dict(d="2g",k="short",m=1,q="Mei-Ling’s first dumpling “looked like a squashed slipper”. Why did the writer use this comparison?",a="To help the reader picture how flat, messy and badly shaped it was.",g="Accept any answer about helping us picture how untidy or misshapen the dumpling was."),
 dict(d="2d",k="short",m=1,q="How did Mei-Ling feel when Jun laughed at her dumpling? Give a reason from the text.",a="Embarrassed, because her cheeks burned.",g="Accept embarrassed / upset / ashamed with the reason “her cheeks burned”. The reason must come from the text."),
 dict(d="2d",k="short",m=1,q="Why did Po Po tell Mei-Ling that her own dumplings had burst open when she was young?",a="To show Mei-Ling that everyone makes mistakes when they begin, so she would feel better.",g="Accept: to comfort or encourage her / to show that practice helps."),
 dict(d="2c",k="order",m=1,q="Number the events from 1 to 4 to show the order they happened in the story.",items=["Mei-Ling found the coin.","Jun laughed at Mei-Ling’s first dumpling.","Po Po hid a coin in a dumpling.","Po Po showed Mei-Ling how to pinch the pleats."],a=[4,2,3,1],g=Q2),
 dict(d="2b",k="find",m=1,q="Find and copy the words that describe how the kitchen smelt.",a="ginger and warm dough",g="Accept “ginger and warm dough”. Both smells are needed."),
 dict(d="2d",k="short",m=2,q="Give two ways that Mei-Ling improved as she made more dumplings.",a="The pleats began to hold (by the tenth); she was humming / relaxed (by the twentieth).",g="1 mark for each point. Accept: her pleats stayed in place; she became calmer or happier; she felt more confident."),
 dict(d="2b",k="tf",m=1,q="Tick True or False for each sentence.",items=["Mei-Ling was making dumplings for the first time.","Po Po was Mei-Ling’s aunt.","The coin was hidden in a single dumpling.","Jun was unkind to Mei-Ling at the end."],a=["T","F","T","F"],g=TF),
 dict(d="2d",k="short",m=1,q="At the end, why did Po Po give “a secret smile”? What might she have done?",a="She may have made sure the coin was in Mei-Ling’s dumpling, or she was pleased that Jun had been proved wrong.",g="Accept any sensible idea linked to Po Po being happy that Mei-Ling won / helping her confidence."),
 dict(d="2c",k="mc",m=1,q="Which sentence best sums up the whole story?",opts=["A girl learns to be patient and finds her first dumpling brings luck.","A boy teases his cousin about her cooking.","A family moves to a new flat before the New Year.","A grandmother loses her silver coin."],a="A"),
 dict(d="2e",k="short",m=1,q="Do you think Mei-Ling will help make dumplings next year? Explain your answer.",a="Yes, because she has learned how to make them and has enjoyed herself / won the coin.",g="Accept yes with a reason from the story (improved, enjoyed it, luck, Jun stopped teasing)."),
])

T(26, "26-5", "How Rain Is Made", "Explanation", [
"Every drop of rain that has ever fallen belongs to an endless journey known as the water cycle. Because the same water is used over and over again, the rain that fell on your school this morning may once have been part of a river, a puddle, or even the sea.",
"The journey begins with the Sun, whose heat warms the water in oceans, lakes and rivers. As the water warms, some of it changes into an invisible gas called water vapour, and this process is called evaporation. Although you cannot see vapour rising into the air, it is happening constantly, which is why puddles disappear on a sunny day.",
"Warm water vapour drifts upwards, and the higher it climbs, the colder the surrounding air becomes. When the vapour cools, it changes back into tiny droplets of liquid water. This change is known as condensation. You can observe it at home whenever steam from a hot bath meets a cold mirror and turns into a film of drops.",
"High in the sky, the droplets gather around minute specks of dust, and millions upon millions of them cluster together to form a cloud. Each droplet is so light that it is held up by the moving air. Clouds may look like solid cotton wool, but they are really made of water droplets and, where the air is very cold, tiny crystals of ice.",
"Inside the cloud, the droplets constantly collide and merge, so that they gradually grow larger. Eventually a drop becomes too heavy for the air to support, and it begins to fall. If the air beneath the cloud is warm enough, the drop reaches the ground as rain; if the air is freezing, it may arrive as snow or hail instead.",
"When the rain lands, some of it soaks into the soil, where plants absorb it through their roots. The rest runs across the ground into streams and rivers, which carry it back to the sea, and the whole journey can start again.",
"Different kinds of cloud bring different kinds of weather. Tall, thick, dark clouds usually hold the most water, because they contain vast numbers of droplets, and that is why the heaviest rain tends to fall from them. Thin, high clouds, on the other hand, are generally made of ice crystals, and they seldom produce rain at all.",
"Without the water cycle, there would be no fresh water for people, animals or plants. Rain may spoil a picnic, but it is one of the most valuable gifts that we receive from the sky.",
], [
 dict(d="2b",k="mc",m=1,q="What gives the water in oceans, lakes and rivers its heat?",opts=["The wind","The clouds","The Sun","The rain"],a="C"),
 dict(d="2a",k="mc",m=1,q="In paragraph 2, what is “evaporation”?",opts=["Water turning into ice","Water turning into a gas called water vapour","Water flowing into a river","Water falling from a cloud"],a="B"),
 dict(d="2b",k="find",m=1,q="Find and copy the word from paragraph 3 that names the change from a gas back into a liquid.",a="condensation",g="Accept “condensation” only."),
 dict(d="2d",k="short",m=1,q="Why do puddles disappear on a sunny day?",a="The heat from the Sun makes the water evaporate into the air.",g="Accept: the water evaporates / turns into water vapour."),
 dict(d="2c",k="order",m=1,q="Number the steps from 1 to 4 to show how rain is made.",items=["Drops join together and become too heavy.","Water vapour cools and forms tiny drops.","The Sun warms the water.","Rain falls."],a=[3,2,1,4],g=Q2),
 dict(d="2b",k="tf",m=1,q="Tick True or False for each sentence.",items=["Water vapour is easy to see.","Clouds are made of tiny drops of water.","Rain water can end up back in the sea.","The water cycle happens only once."],a=["F","T","T","F"],g=TF),
 dict(d="2d",k="short",m=1,q="What does the steamy mirror example show about condensation?",a="That water vapour turns into drops of water when it touches something cold.",g="Accept: condensation happens when vapour meets a cold surface / cools."),
 dict(d="2d",k="short",m=1,q="Why can tiny drops of water in a cloud float in the sky?",a="Each drop is so light that the moving air holds it up.",g="Accept: they are very light."),
 dict(d="2d",k="short",m=1,q="Why might thin, high clouds seldom bring rain?",a="They are made of ice crystals and hold much less water than tall, thick clouds.",g="Accept: they are thin and hold few drops / they are ice."),
 dict(d="2c",k="mc",m=1,q="Which sentence best sums up paragraph 6?",opts=["Plants do not need rain.","Rain flows or soaks in and the cycle starts again.","Rivers dry up in summer.","Soil is made from rain."],a="B"),
 dict(d="2g",k="short",m=1,q="The writer says clouds may look like “solid cotton wool”. Why does the writer use this comparison?",a="To help the reader picture how soft and solid clouds look.",g="Accept any answer about helping the reader picture the appearance of clouds."),
 dict(d="2b",k="short",m=1,q="Where does some of the rain water go after it lands, apart from into rivers?",a="Into the soil, where plants absorb it.",g="Accept: it soaks into the soil / is taken in by plants."),
 dict(d="2c",k="mc",m=1,q="What is the main idea of this text?",opts=["Water moves in a never-ending cycle which makes rain.","Rain is bad for picnics.","The Sun is a large star.","Snow and hail are the same thing."],a="A"),
])

T(27, "27-1", "Fog on Carrow Ridge", "Narrative", [
"Amara had been looking forward to the hike for weeks, ever since her dad had promised that at the top of Carrow Ridge there stood a stone hut where they could eat hot soup and gaze across three valleys. She, her dad and her little brother Kwame set off early, when the morning was still clear and bright, and the path wound steadily upwards between bracken and silver birch trees. Kwame, who had far more energy than sense, ran on ahead, pretending to be a mountain goat.",
"After an hour, the trees thinned and the ground turned rocky, and a cold wind began to push at their backs. Dad glanced up towards the ridge, and Amara noticed a small frown crease his forehead. A grey cloud was sliding down the hillside towards them, as slowly and softly as a wave rolling up a beach. “Stay close,” he said. “Both of you.”",
"Within minutes the fog had wrapped itself around them, so thick that Amara could see no further than her own outstretched arm. The path had vanished, and every rock looked exactly like the next. Kwame slipped his hand into hers. “Are we lost?” he whispered. Although her heart was thumping, Amara answered as calmly as she could. “Dad will know what to do.”",
"Dad stood very still for a moment, thinking. “We do not need to see the summit,” he said at last. “Remember the blue paint on the stones? The rangers mark the path with blue dots, so all we have to do is find the next one.” They formed a line, holding hands, and stretched out as far as they dared, searching the ground on every side. A few steps away, Amara spotted a small blue circle on a flat grey stone. “Here!” she called.",
"They crept forward from dot to dot, sometimes finding the marks close together and sometimes having to spread out and feel their way across the damp rock. Kwame turned it into a game, counting each dot aloud, and Amara noticed that the fear that had knotted her stomach was slowly loosening. It was difficult to feel afraid when the three of them were working together so well.",
"After what seemed an age, the ground levelled off and a square shape appeared in the murk. It was the stone hut, its wooden door painted exactly the same blue as the dots. Inside, a small wood stove glowed, and a friendly couple in bobble hats poured them each a mug of tomato soup, which Amara held in both hands while the warmth crept into her frozen fingers.",
"An hour later, the wind changed direction and the fog began to tear apart into ragged strips. Sunlight poured through the gaps, and below them lay three green valleys, shining as if somebody had polished them. Kwame pressed his nose against the window. “It was worth it,” he said. Dad grinned at Amara. “It was, wasn’t it?” he said quietly. “And you led us wonderfully well, you know.” Amara felt taller than the ridge itself.",
], [
 dict(d="2b",k="mc",m=1,q="Where were Amara, Kwame and Dad hoping to have hot soup?",opts=["In a stone hut at the top of the ridge","In a café in the valley","In a car at the bottom of the hill","At a picnic table beside the path"],a="A"),
 dict(d="2b",k="find",m=1,q="Find and copy one word from paragraph 3 that tells you the fog was very dense.",a="thick",g="Accept “thick” only."),
 dict(d="2a",k="mc",m=1,q="In paragraph 5, what does the word “crept” suggest about how they moved?",opts=["Very quickly","Noisily","Slowly and carefully","Without any care"],a="C"),
 dict(d="2d",k="short",m=1,q="What tells you that Dad was worried when he looked up at the ridge in paragraph 2?",a="A small frown creased his forehead / he told them to stay close.",g="Accept either clue."),
 dict(d="2g",k="short",m=1,q="The writer says the fog had “wrapped itself around them”. What does this word choice suggest about the fog?",a="That it surrounded them closely and completely, like a blanket.",g="Accept any answer about the fog closing in on all sides."),
 dict(d="2c",k="order",m=1,q="Number the events from 1 to 4 to show the order they happened in the story.",items=["Amara found the first blue dot.","Fog rolled down the hillside.","The family drank tomato soup.","The fog cleared to show three valleys."],a=[2,1,3,4],g=Q2),
 dict(d="2d",k="short",m=1,q="Amara answered Kwame “as calmly as she could”. How was she really feeling?",a="Scared / worried, but she was trying to stay calm for Kwame.",g="Accept: frightened or anxious. Clue: her heart was thumping."),
 dict(d="2d",k="short",m=1,q="Why did Amara’s fear start to loosen as they followed the dots?",a="Because they were working as a team and had a plan.",g="Accept: they were doing something useful together / following a plan."),
 dict(d="2b",k="tf",m=1,q="Tick True or False for each sentence.",items=["The rangers marked the path with blue paint.","Kwame found the first blue dot.","The stone hut had a blue door.","The family walked in silence."],a=["T","F","T","F"],g=TF),
 dict(d="2d",k="short",m=2,q="Give two ways that Dad helped his children to stay safe in the fog.",a="He told them to stay close; he stayed still and thought; he reminded them about the blue dots; he had them hold hands and search in a line.",g="1 mark for each way. Max 2."),
 dict(d="2d",k="short",m=1,q="Why did Amara feel “taller than the ridge itself” at the end?",a="She felt proud because Dad had said she led them well.",g="Accept: proud / pleased / important, linked to Dad’s praise."),
 dict(d="2c",k="mc",m=1,q="Which sentence best sums up the story?",opts=["A family gets lost and never reaches the top.","A family follows a trail through fog to reach a hut and a lovely view.","A boy discovers a hut in the mountains.","A ranger rescues a family in bad weather."],a="B"),
 dict(d="2g",k="short",m=1,q="The valleys are described as “shining as if somebody had polished them”. What effect does this have on the reader?",a="It makes the view seem clean, bright and beautiful.",g="Accept any answer about brightness, beauty or a fresh, gleaming look."),
 dict(d="2e",k="short",m=1,q="Do you think Amara will want to go hiking again? Explain your answer.",a="Yes, because she felt proud and enjoyed the view / she became brave.",g="Accept a prediction with a reason from the story."),
])

T(27, "27-3", "The Attic at Nana Joy’s", "Description", [
"The ladder to Nana Joy’s attic creaks on every single rung, as if it resents being woken from a long sleep. At the top, a small wooden hatch swings open, and out drifts the smell of the past: dust, old paper and a faint, sweet trace of lavender. I clamber through carrying a torch, although I do not really need it, because a round window at the far end lets in a long beam of afternoon light, and within it thousands of dust specks drift like tiny sparkling planets.",
"The attic is a crowded place. Boxes are stacked all the way up to the rafters, each labelled in Nana’s loopy handwriting: “Christmas”, “Mum’s books”, “Cables (do not throw)”. In one corner stands a rocking horse with a single glass eye, and it seems to follow me wherever I move. Above my head, a row of coats hangs from a beam, their sleeves swaying gently in the draught, and I half expect one of them to reach out and wave.",
"I kneel beside a trunk with brass corners that generations of hands have polished to a soft glow. The lid opens with a satisfying groan, and inside lies a bundle of silk scarves in ruby, emerald and gold, folded as precisely as envelopes. Beneath them rests a pair of tiny ballet shoes, their ribbons faded to the colour of weak tea. I lift one to my nose, and it smells of chalk and of a very long time ago.",
"At the very bottom of the trunk I discover a photograph in a cardboard frame. A young woman in a sparkling costume is laughing at the camera, one leg lifted and both arms flung wide as though she is about to take flight. On the back, in faded pencil, someone has written: “Joy, opening night, 1968.” I turn the picture over again and study the face properly. The nose is the same, and so are the crinkles around the eyes.",
"From below, a voice calls up the ladder. “Have you found anything interesting?” Nana Joy pokes her head through the hatch, her cheeks pink from the climb, and then she sees the photograph in my hands and stops. For a moment the attic is completely silent, and the dust hangs motionless in the light.",
"“Ah,” she says, with a small, astonished laugh. “I wondered where that had gone.” She lowers herself onto a box and takes the photograph as tenderly as if it were a butterfly. “I had forgotten how much I loved that stage,” she murmurs. “Shall I tell you about it?”",
"I nod. Outside, the light is slowly turning from white to honey. The rocking horse keeps its glass eye fixed on us, and I settle down among the scarves to listen, thinking that an attic is not a place for old things at all. It is a place where stories wait.",
], [
 dict(d="2b",k="mc",m=1,q="What is the main thing that lights the attic?",opts=["A round window","A lamp on the ceiling","Candles","A torch left by Nana Joy"],a="A"),
 dict(d="2a",k="mc",m=1,q="In paragraph 3, what does the word “polished” suggest about the trunk?",opts=["It was rusty","It was shiny and cared for","It was brand new","It was very heavy"],a="B"),
 dict(d="2b",k="find",m=1,q="Find and copy the words that tell you what colour the ballet shoe ribbons had faded to.",a="the colour of weak tea",g="Accept “the colour of weak tea” or “weak tea”."),
 dict(d="2g",k="short",m=1,q="The writer says the dust drifted “like tiny sparkling planets”. What does this comparison suggest about the dust?",a="That it looked beautiful and glittering as it floated slowly in the light.",g="Accept: sparkling, floating, magical or peaceful."),
 dict(d="2d",k="short",m=1,q="The ladder creaks “as if it resents being woken from a long sleep”. What does this suggest about the attic?",a="That nobody had been up there for a long time.",g="Accept: it is old / not often used / creaky."),
 dict(d="2d",k="short",m=1,q="What clues in paragraph 4 suggest that the woman in the photograph was Nana Joy?",a="The name Joy on the back; the same nose and crinkles around the eyes.",g="Accept either clue, or both."),
 dict(d="2d",k="short",m=1,q="The rocking horse “seems to follow me wherever I move”. What feeling does this create?",a="A slightly spooky or mysterious feeling, as if the attic were alive.",g="Accept: curious, strange, eerie, watched. Accept any answer about the attic feeling alive."),
 dict(d="2c",k="order",m=1,q="Number the events from 1 to 4 to show the order they happened in the text.",items=["Nana Joy took the photograph.","The narrator climbed the ladder.","The narrator found the photograph.","The narrator opened the trunk."],a=[4,1,3,2],g=Q2),
 dict(d="2b",k="tf",m=1,q="Tick True or False for each sentence.",items=["The scarves were folded neatly.","The photograph was taken in 1968.","Nana Joy was cross with the narrator.","The rocking horse had two glass eyes."],a=["T","T","F","F"],g=TF),
 dict(d="2d",k="short",m=2,q="Give two details that show Nana Joy was surprised and moved by the photograph.",a="She stopped; the attic went silent; she gave a small, astonished laugh; she took it tenderly, like a butterfly; she said she had forgotten how much she loved the stage.",g="1 mark for each. Max 2."),
 dict(d="2d",k="short",m=1,q="Why do you think the narrator does not “really need” the torch?",a="Because the round window lets in enough light.",g="Accept: it was bright enough inside."),
 dict(d="2c",k="mc",m=1,q="Which sentence best sums up the text?",opts=["A child finds a photograph in an attic and learns something new about a grandmother.","A child is frightened of a rocking horse.","A grandmother clears out her attic.","A child loses a torch in the dark."],a="A"),
 dict(d="2g",k="short",m=1,q="The narrator ends by saying an attic is “a place where stories wait”. What does this mean?",a="The old objects in the attic each have a story behind them, waiting to be told.",g="Accept any answer about objects holding memories or stories."),
 dict(d="2e",k="short",m=1,q="What do you think Nana Joy will do next? Give a reason.",a="She will tell the story of her time on stage, because she asked if she should.",g="Accept a prediction with a reason from the text."),
])

T(27, "27-4", "Should Our Valley Have a Wind Farm?", "Discussion", [
"A company has asked to build twelve wind turbines on the hills above Little Marlow, and the valley is divided. Some people think the plan is a good one. Others are firmly against it. Before you decide what you think, it helps to look at both sides.",
"Supporters point out that wind turbines make electricity without burning coal, oil or gas. Burning fuels releases gases that warm the planet, but a spinning turbine releases none. Wind is also a source that never runs out, unlike fuels, which take millions of years to form. Twelve turbines could make enough electricity for several thousand homes. The company has also promised that some of the money it earns would help to pay for a new village hall.",
"Supporters also say that turbines are a sensible use of a windy place. The hills above Little Marlow are exposed and breezy for much of the year, so the blades would turn on most days. A wind farm can be built in months, while a power station may take years. A farmer who lets the company use a field is paid rent for it. If the turbines were ever removed, the land could go back to farming, because they stand on small concrete bases and do not damage the soil.",
"Opponents, however, worry about how the hills would look. Turbines can be over a hundred metres tall, and they can be seen from many kilometres away. People who love the view fear that the peaceful skyline would be spoilt. Walkers and tourists might stop visiting, and local cafés and B&Bs could lose customers.",
"Some neighbours are also concerned about noise. When turbines turn, the blades make a soft whooshing sound. The people who live nearest say it might disturb them, especially at night. Others worry about wild birds, which can be harmed if they fly into the blades. However, experts say that careful planning of where to put the turbines can reduce this risk.",
"Finally, there is the question of reliability. Turbines produce electricity only when the wind blows at the right speed. On a calm day they produce very little, so the valley would still need other sources of power to keep the lights on. Opponents say this shows that turbines cannot be the whole answer. They believe the money might be better spent on other ideas, such as covering roofs with solar panels.",
"In conclusion, the wind farm would help to reduce pollution and bring money to the village. However, it would change the landscape, and it may bother some of the people who live nearby. Each person has to weigh up how much they value cleaner energy against the beauty and quiet of the hills. Whatever the outcome, everyone in the valley deserves the chance to have their say.",
], [
 dict(d="2b",k="mc",m=1,q="How many turbines does the company want to build?",opts=["Six","Ten","Twelve","Twenty"],a="C"),
 dict(d="2a",k="mc",m=1,q="In paragraph 1, what does the word “divided” mean?",opts=["Sharing the same view","Split into groups with different opinions","Quiet and calm","Joined together"],a="B"),
 dict(d="2b",k="find",m=1,q="Find and copy the word from paragraph 4 that means “worried”.",a="worry",g="Accept “worry” (“concerned” is in paragraph 5)."),
 dict(d="2d",k="short",m=1,q="Why do supporters say wind is better than coal, oil or gas?",a="A spinning turbine gives out no warming gases, and wind never runs out.",g="Accept either reason."),
 dict(d="2d",k="short",m=1,q="What might the company’s promise about the village hall be trying to do?",a="Persuade people in the village to agree with the plan.",g="Accept: encourage support / win people over."),
 dict(d="2c",k="mc",m=1,q="Which of these is the best heading for paragraph 5?",opts=["Noise and birds","How to build a turbine","Money for the village","Why walkers visit"],a="A"),
 dict(d="2b",k="tf",m=1,q="Tick True or False for each sentence.",items=["Turbines can be more than a hundred metres tall.","Wind turbines produce a lot of power on calm days.","The turbines stand on small concrete bases.","All the people of the valley agree about the plan."],a=["T","F","T","F"],g=TF),
 dict(d="2d",k="short",m=1,q="Why might cafés and B&Bs lose customers if the turbines are built?",a="Visitors may no longer want to come to see the hills once the view is spoilt.",g="Accept: fewer tourists and walkers."),
 dict(d="2d",k="short",m=1,q="Why does the writer mention that experts say careful planning can reduce the risk to birds?",a="To show that the problem might be lessened; to be fair to both sides.",g="Accept: it shows the problem can be reduced / to give a balanced view."),
 dict(d="2c",k="order",m=1,q="Number the sections from 1 to 4 to show the order they appear in the text.",items=["The conclusion","Arguments for the wind farm","The question of reliability","Arguments against the wind farm about the view"],a=[4,1,3,2],g=Q2),
 dict(d="2g",k="short",m=1,q="The writer describes the sound of turbines as “a soft whooshing sound”. Does the writer make the noise seem loud or gentle? Explain.",a="Gentle, because the words “soft” and “whooshing” suggest a quiet sound.",g="Accept gentle/quiet with a word from the text."),
 dict(d="2d",k="short",m=2,q="Give two problems with turbines that opponents mention.",a="They spoil the view; they might make noise; they could harm birds; they only make electricity when it is windy.",g="1 mark for each. Max 2. Accept any two."),
 dict(d="2c",k="mc",m=1,q="What is the writer’s purpose in this text?",opts=["To force readers to agree with the plan","To set out both sides so that readers can make up their own minds","To explain how a turbine works","To tell a story about a village"],a="B"),
 dict(d="2e",k="short",m=1,q="Why might some people change their minds after reading both sides?",a="They may realise that there are good and bad points on each side.",g="Accept any sensible answer that links to the balanced presentation."),
])

T(25, "25-4", "The Harbour Before Sunrise", "Description", [
"The harbour is still asleep when I arrive, wrapped in a blanket of cool, grey half-light. Nothing moves except the water, which slaps softly against the stone wall and slides away again, over and over, like someone breathing in their sleep. The air tastes of salt and rope and cold metal, and my breath hangs in front of me in small white clouds.",
"Along the quay, the boats bob at their moorings in tidy rows. There are rowing dinghies painted in faded reds and blues, a squat little ferry with a striped funnel, and a tall sailing boat whose mast rocks slowly from side to side, ticking against its ropes like a clock. Each boat has a name lettered on its stern in curling gold paint: Wren, Sea Biscuit, Marigold. I wonder who chose them, and whether they still remember why.",
"Then the sky begins to change. First, a thin line of pale pink creeps along the horizon, as if someone were drawing it with a fine pencil. Slowly the line widens and deepens, spilling orange across the clouds and washing the whole bay in a glow the colour of apricots. The windows of the tall, narrow houses on the hill catch the light one by one, and they flash as though they were waking up and winking at the sea.",
"Now the harbour begins to stir. A gull lands on a bollard and lets out a harsh, scornful cry, and within seconds the air is full of white wings and squabbling. Somewhere behind me a door bangs, and the smell of warm bread drifts down from the bakery at the end of the lane. A man in a yellow jacket strolls along the quay, jangling a bunch of keys. He unlocks the hatch of the ferry, and the engine coughs, splutters and then settles into a low, comfortable purr.",
"By the time the sun finally lifts clear of the water, everything has changed. The grey has melted away, and the harbour blazes with colour: the red of the dinghies, the gold of the lettering, the deep green of the weed on the steps. Even the puddles on the cobbles are shining. I sit on the edge of the wall with my feet dangling and my hands wrapped round a warm bread roll, and I decide that this is the best hour of the whole day.",
], [
 dict(d="2b",k="mc",m=1,q="In paragraph 1, how does the water move against the harbour wall?",opts=["It roars loudly","It slaps softly","It crashes violently","It drips slowly"],a="B"),
 dict(d="2b",k="find",m=1,q="Find and copy one word from paragraph 2 that tells you the ferry is short and wide.",a="squat",g="Accept “squat” only."),
 dict(d="2a",k="mc",m=1,q="In paragraph 4, what does the word “scornful” suggest about the gull’s cry?",opts=["Frightened","Cheerful","Sleepy","Showing no respect"],a="D"),
 dict(d="2b",k="short",m=2,q="Give two things the narrator can see along the quay in paragraph 2.",a="Rowing dinghies; a ferry (with a striped funnel); a tall sailing boat.",g="1 mark for each. Accept any two of: dinghies / rowing boats; ferry; sailing boat / mast. Max 2."),
 dict(d="2g",k="short",m=1,q="The pink line on the horizon is described as if someone were “drawing it with a fine pencil”. What does this suggest about the line?",a="That it was thin, delicate and neat.",g="Accept: thin, fine, delicate, careful."),
 dict(d="2d",k="short",m=1,q="What time of day is being described? Give one clue from the text.",a="Early morning / dawn, because the sky is grey and a pink line appears on the horizon before the sun rises.",g="1 mark for early morning / dawn / sunrise with a clue such as half-light, the sun lifting, bread from the bakery, or the harbour being asleep."),
 dict(d="2c",k="order",m=1,q="Number the events from 1 to 4 to show the order they happened in the text.",items=["A gull landed on a bollard.","A pink line appeared on the horizon.","The narrator sat on the wall with a bread roll.","The ferry engine started."],a=[2,1,4,3],g=Q2),
 dict(d="2b",k="tf",m=1,q="Tick True or False for each sentence.",items=["The boats are lined up in tidy rows.","The ferry has a striped funnel.","The narrator arrives after the sun has risen.","The gulls stay silent."],a=["T","T","F","F"],g=TF),
 dict(d="2d",k="short",m=1,q="The narrator wonders “who chose” the boat names “and whether they still remember why”. What does this show about the narrator?",a="That the narrator is curious and imagines stories behind the names.",g="Accept: curious / thoughtful / interested in the boats’ history."),
 dict(d="2d",k="short",m=1,q="How can you tell that the narrator enjoys being at the harbour? Give one piece of evidence.",a="The narrator decides it is the best hour of the day; sits with feet dangling; enjoys a warm bread roll.",g="Accept any one relevant piece of evidence from paragraph 5."),
 dict(d="2c",k="mc",m=1,q="Which sentence best sums up paragraph 3?",opts=["The sunrise fills the sky and the houses with colour.","A storm is coming towards the bay.","The houses are being painted.","The narrator gets lost on the hill."],a="A"),
 dict(d="2d",k="mc",m=1,q="Which word best describes how the narrator feels at the end of the text?",opts=["Anxious","Bored","Contented","Furious"],a="C"),
 dict(d="2e",k="short",m=1,q="Do you think the narrator will come back to the harbour? Give a reason from the text.",a="Yes, because the narrator thinks it is the best hour of the day.",g="Accept yes with a reason based on the narrator’s enjoyment."),
])

T(25, "25-6", "The Night the Tent Came Down", "Narrative", [
"Zainab had packed the rucksack herself, and she was rather proud of it. It held torches, spare socks, a bag of marshmallows and, tucked into a side pocket, a small repair kit that Grandad had pressed into her hand before they left. “You never know,” he had said. Zainab had rolled her eyes, but she had packed it anyway.",
"By late afternoon, Dad and her younger brother Idris had put up the tent in a sheltered corner of the campsite, right beside a chattering stream. They cooked sausages on the stove, toasted the marshmallows until they were black and gooey, and watched the sun slip behind the hills. When it grew dark, the three of them wriggled into their sleeping bags and lay listening to the water. “This,” murmured Dad, “is the life.”",
"Zainab woke suddenly in the middle of the night. The tent walls were flapping like enormous wings, and the wind was howling around the campsite. Then came a sharp crack, and one side of the tent folded slowly inwards, draping cold, damp fabric over her face. “Dad!” squealed Idris. “Everyone stay calm,” said Dad, fumbling for the torch. “A pole has snapped, that is all.”",
"There was no question of mending it in the dark. Dad bundled the children into their sleeping bags, carried them across the field one at a time, and settled them on the back seat of the car, where the wind could not reach them. Rain began to patter on the roof. Idris fell asleep almost at once, but Zainab lay awake, thinking about the tent and about the little kit in her rucksack.",
"By morning the wind had died, and the sky had turned a clean, rinsed blue. The tent lay crumpled on the grass like a giant, deflated balloon, with the broken pole poking out at a sorry angle. Dad scratched his head. “We may have to go home,” he said. “I cannot see how to fix that.”",
"“Wait,” said Zainab. She fetched the repair kit and unrolled it on the grass. Inside lay a short metal sleeve, exactly the right width, and a roll of strong tape. She slid the sleeve over the crack, as Grandad had once shown her, and wound the tape tightly round it until the pole stood straight again. Dad stared. Then, very slowly, he began to laugh.",
"By breakfast time the tent was standing once more, a little crooked but perfectly sound. Zainab sat in the sunshine with a bowl of steaming porridge, and Idris held out a marshmallow on a stick. “Next time,” said Dad, “you are in charge of the packing.” “Next time,” grinned Zainab, “I am also in charge of the tent.”",
], [
 dict(d="2b",k="mc",m=1,q="What did Grandad give Zainab before they left?",opts=["A torch","A repair kit","A bag of marshmallows","A map"],a="B"),
 dict(d="2b",k="short",m=1,q="Where did Dad and Idris put up the tent?",a="In a sheltered corner of the campsite, beside a stream.",g="Accept: next to the stream / in a sheltered corner."),
 dict(d="2a",k="mc",m=1,q="In paragraph 3, what does the word “draping” suggest about the fabric?",opts=["Hanging loosely over her","Tearing into pieces","Being tied tightly","Blowing far away"],a="A"),
 dict(d="2d",k="short",m=1,q="Why do you think Zainab rolled her eyes when Grandad gave her the repair kit?",a="She did not think she would need it.",g="Accept: she thought it was unnecessary / silly / that nothing would go wrong."),
 dict(d="2g",k="short",m=1,q="The writer says the tent walls were “flapping like enormous wings”. What does this suggest about the wind?",a="That it was very strong and made the tent move wildly.",g="Accept: strong / powerful / noisy / violent movement."),
 dict(d="2c",k="order",m=1,q="Number the events from 1 to 4 to show the order they happened in the story.",items=["Zainab mended the pole.","The children slept in the car.","A pole snapped.","Dad and Idris put up the tent."],a=[4,3,2,1],g=Q2),
 dict(d="2d",k="short",m=2,q="Give two things Dad did to keep the children safe after the pole snapped.",a="He told everyone to stay calm; he carried the children across the field; he settled them in the car away from the wind.",g="1 mark for each. Accept any two of: stayed calm / reassured them; carried them to the car; put them in the car out of the wind and rain."),
 dict(d="2b",k="tf",m=1,q="Tick True or False for each sentence.",items=["Zainab packed the rucksack herself.","The tent was put up in an open, windy spot.","It rained after the children moved to the car.","Dad mended the pole."],a=["T","F","T","F"],g=TF),
 dict(d="2d",k="short",m=1,q="Dad says, “We may have to go home.” What does this tell you about how he felt?",a="He felt unsure or disappointed and was ready to give up.",g="Accept: worried / defeated / disappointed / did not know what to do."),
 dict(d="2b",k="find",m=1,q="Find and copy the words that tell you what the collapsed tent looked like in paragraph 5.",a="like a giant, deflated balloon",g="Accept “like a giant, deflated balloon” or “giant, deflated balloon”."),
 dict(d="2d",k="mc",m=1,q="Why did Dad begin to laugh at the end of paragraph 6?",opts=["He thought the pole looked funny","He was cross with Zainab","He was amazed and pleased that Zainab had solved the problem","He wanted to go home"],a="C"),
 dict(d="2c",k="mc",m=1,q="Which sentence best sums up the story?",opts=["A family goes home early after a storm.","A girl is frightened of camping.","Dad and Idris build a tent by a stream.","A camping trip is saved when a girl mends the broken tent pole."],a="D"),
 dict(d="2e",k="short",m=1,q="Do you think Zainab will pack the rucksack next time? Explain your answer.",a="Yes, because Dad said she would be in charge of the packing and her repair kit saved the trip.",g="Accept yes with a reason from paragraph 7 or the earlier events."),
])
